    if (delegateUserId === member.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: member.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

/** Clears a member's absence. Clearing when none is set is not an error. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);

  await memberRepo.deleteAbsence(orgId, member.userId);
}

/**
 * The member's absence while it still matters: one that is running or has yet
 * to start. Once the end has passed it reads as `null`, the same as never
 * having been set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));

  const member = await requireActiveMember(orgId, userId);

  const absence = await memberRepo.findAbsence(orgId, member.userId);
  if (absence === null) return null;

  return Date.now() < Date.parse(absence.endsAt) ? absence : null;
}

/**
 * Who stands in for `userId` at the instant `at`: their delegate, when they
 * are away at that instant and named one who is still an active member —
 * otherwise `null`, meaning "nobody, deal with the member directly".
 *
 * Deliberately a single hop. The delegate's own absence is never consulted, so
 * a redirect cannot chain or loop. Takes no `Actor`: the callers are the
 * assignment path and the notification fan-out, which redirect on behalf of
 * the organization rather than of whoever triggered them.
 */
export async function findStandIn(
  orgId: OrgId,
  userId: UserId,
  at: Date | IsoTimestamp,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;
  if (!coversInstant(absence, at)) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (delegate === null || delegate.status !== "active") return null;

  return delegate.userId;
}

/** Half-open window test: the start is inside the absence, the end is not. */
function coversInstant(absence: MemberAbsence, at: Date | IsoTimestamp): boolean {
  const instant = typeof at === "string" ? Date.parse(at) : at.getTime();
  return (
    instant >= Date.parse(absence.startsAt) &&
    instant < Date.parse(absence.endsAt)
  );
}

/**
 * Absences belong to people currently in the organization. A removed member,
 * or a user who only belongs to another organization, is reported exactly
 * like a user who does not exist.
 */
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/** Your own absence is yours to manage; anyone else's needs `member:update_role`. */
function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

