/**
 * Out of office: setting, reading and clearing an absence, and the three
 * places it changes behaviour — assignment, overdue alerts and mentions.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { issueResource, NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import {
  clearAbsence,
  getAbsence,
  removeMember,
  setAbsence,
} from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { NotificationKind } from "@/types/notification";

const HOUR = 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

function at(offsetMs: number): IsoTimestamp {
  return toIsoTimestamp(new Date(Date.now() + offsetMs));
}

/** Puts `userId` out of office for an hour either side of now. */
async function setAway(
  tenant: Tenant,
  userId: UserId,
  delegateUserId: UserId | null,
): Promise<void> {
  await setAbsence(tenant.actors.owner, {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: at(-HOUR),
    endsAt: at(HOUR),
    note: null,
  });
}

async function alertsFor(
  tenant: Tenant,
  recipientId: UserId,
  kind: NotificationKind,
) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function memberIdOf(tenant: Tenant, userId: UserId) {
  const member = await memberRepo.findMember(tenant.org.id, userId);
  if (!member) throw new Error("fixture member missing");
  return member.id;
}

describe("setAbsence / getAbsence / clearAbsence", () => {
  it("stores the window and resolves to exactly what was stored", async () => {
    const tenant = await createTenant("absence-store");
    const input = {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: at(-HOUR),
      endsAt: at(HOUR),
      note: "On holiday",
    };

    const stored = await setAbsence(tenant.actors.member, input);

    expect(stored).toEqual(input);
    expect(
      await getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).toEqual(input);
  });

  it("replaces the previous absence when set again", async () => {
    const tenant = await createTenant("absence-replace");
    await setAway(tenant, tenant.userIds.member, tenant.userIds.admin);

    const replacement = {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: at(2 * HOUR),
      endsAt: at(3 * HOUR),
      note: "Later",
    };
    await setAbsence(tenant.actors.member, replacement);

    expect(
      await getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).toEqual(replacement);
  });

  it("returns a scheduled absence, and null once it has ended or when none is set", async () => {
    const tenant = await createTenant("absence-read");
    const { org, actors, userIds } = tenant;

    expect(await getAbsence(actors.owner, org.id, userIds.member)).toBeNull();

    await setAbsence(actors.member, {
      orgId: org.id,
      userId: userIds.member,
      delegateUserId: null,
      startsAt: at(HOUR),
      endsAt: at(2 * HOUR),
      note: null,
    });
    expect(await getAbsence(actors.owner, org.id, userIds.member)).not.toBeNull();

    await setAbsence(actors.member, {
      orgId: org.id,
      userId: userIds.member,
      delegateUserId: null,
      startsAt: at(-2 * HOUR),
      endsAt: at(-HOUR),
      note: null,
    });
    expect(await getAbsence(actors.owner, org.id, userIds.member)).toBeNull();
  });

  it("clears an absence, and tolerates clearing when none is set", async () => {
    const tenant = await createTenant("absence-clear");
    const { org, actors, userIds } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);

    await clearAbsence(actors.member, org.id, userIds.member);
    expect(await getAbsence(actors.owner, org.id, userIds.member)).toBeNull();

    await expect(
      clearAbsence(actors.member, org.id, userIds.member),
    ).resolves.toBeUndefined();
  });

  it("rejects a window that does not end after it starts", async () => {
    const tenant = await createTenant("absence-window");
    const instant = at(HOUR);

    for (const endsAt of [instant, at(0)]) {
      await expect(
        setAbsence(tenant.actors.member, {
          orgId: tenant.org.id,
          userId: tenant.userIds.member,
          delegateUserId: null,
          startsAt: instant,
          endsAt,
          note: null,
        }),
      ).rejects.toThrow(/end after it starts/);
    }
  });

  it("rejects the member as their own delegate", async () => {
    const tenant = await createTenant("absence-self-delegate");

    await expect(
      setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.member,
        startsAt: at(-HOUR),
        endsAt: at(HOUR),
        note: null,
      }),
    ).rejects.toThrow(/own delegate/);
  });

  it("requires the member and the delegate to be active members of the workspace", async () => {
    const tenant = await createTenant("absence-membership");
    const other = await createTenant("absence-membership-other");
    const { org, actors, userIds } = tenant;
    const window = { startsAt: at(-HOUR), endsAt: at(HOUR), note: null };

    await expect(
      setAbsence(actors.owner, {
        orgId: org.id,
        userId: other.userIds.member,
        delegateUserId: null,
        ...window,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      setAbsence(actors.owner, {
        orgId: org.id,
        userId: userIds.member,
        delegateUserId: other.userIds.admin,
        ...window,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await removeMember(actors.owner, {
      orgId: org.id,
      memberId: await memberIdOf(tenant, userIds.viewer),
    });

    await expect(
      setAbsence(actors.owner, { orgId: org.id, userId: userIds.viewer, delegateUserId: null, ...window }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      setAbsence(actors.owner, { orgId: org.id, userId: userIds.member, delegateUserId: userIds.viewer, ...window }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      getAbsence(actors.owner, org.id, userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      getAbsence(actors.owner, org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets members manage only their own absence, and role managers anyone's", async () => {
    const tenant = await createTenant("absence-permissions");
    const { org, actors, userIds } = tenant;
    const window = { delegateUserId: null, startsAt: at(-HOUR), endsAt: at(HOUR), note: null };

    await expect(
      setAbsence(actors.member, { orgId: org.id, userId: userIds.viewer, ...window }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await setAbsence(actors.viewer, { orgId: org.id, userId: userIds.viewer, ...window });
    await setAbsence(actors.admin, { orgId: org.id, userId: userIds.member, ...window });

    await expect(
      clearAbsence(actors.member, org.id, userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await getAbsence(actors.member, org.id, userIds.viewer)).not.toBeNull();

    await clearAbsence(actors.admin, org.id, userIds.viewer);
    expect(await getAbsence(actors.member, org.id, userIds.viewer)).toBeNull();
  });

  it("refuses an orgId outside the actor's workspace on every operation", async () => {
    const tenant = await createTenant("absence-scope");
    const other = await createTenant("absence-scope-other");
    const { actors, userIds } = tenant;

    await expect(
      setAbsence(actors.owner, {
        orgId: other.org.id,
        userId: userIds.owner,
        delegateUserId: null,
        startsAt: at(-HOUR),
        endsAt: at(HOUR),
        note: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      clearAbsence(actors.owner, other.org.id, userIds.owner),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      getAbsence(actors.owner, other.org.id, userIds.owner),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("assignment while away", () => {
  it("hands an assignment to the delegate in every respect", async () => {
    const tenant = await createTenant("absence-assign");
    const { org, actors, userIds, project } = tenant;
    await setAway(tenant, userIds.viewer, userIds.member);

    const issue = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Redirect on assign" }),
    );

    const seen: { previousAssigneeId: UserId | null; assigneeId: UserId }[] = [];
    detachers.push(subscribe("issue.assigned", (payload) => void seen.push(payload)));

    const assigned = await issueService.assignIssue(actors.owner, {
      orgId: org.id,
      issueId: issue.id,
      assigneeId: userIds.viewer,
    });

    expect(assigned.assigneeId).toBe(userIds.member);
    expect((await issueRepo.findIssueById(org.id, issue.id))?.assigneeId).toBe(userIds.member);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ previousAssigneeId: null, assigneeId: userIds.member });

    expect(await alertsFor(tenant, userIds.member, "issue_assigned")).toHaveLength(1);
    expect(await alertsFor(tenant, userIds.viewer, "issue_assigned")).toHaveLength(0);

    // Ownership follows the stored assignee: the away viewer gains nothing.
    expect(can(actors.viewer, "issue:update", issueResource(assigned))).toBe(false);
  });

  it("hands an issue created for an away member to the delegate", async () => {
    const tenant = await createTenant("absence-create");
    const { org, actors, userIds, project } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);

    const seen: (UserId | null)[] = [];
    detachers.push(subscribe("issue.created", (payload) => void seen.push(payload.assigneeId)));

    const issue = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Redirect on create", assigneeId: userIds.member }),
    );

    expect(issue.assigneeId).toBe(userIds.admin);
    expect(seen).toEqual([userIds.admin]);
  });

  it("does not redirect when the away member takes the issue themselves", async () => {
    const tenant = await createTenant("absence-self-take");
    const { org, actors, userIds, project } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);

    const created = await issueService.createIssue(
      actors.member,
      issueInput(org.id, project.id, { title: "Mine from the start", assigneeId: userIds.member }),
    );
    expect(created.assigneeId).toBe(userIds.member);

    const open = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Taken later" }),
    );
    const taken = await issueService.assignIssue(actors.member, {
      orgId: org.id,
      issueId: open.id,
      assigneeId: userIds.member,
    });
    expect(taken.assigneeId).toBe(userIds.member);
  });

  it("never chains: an away delegate still receives the issue", async () => {
    const tenant = await createTenant("absence-chain");
    const { org, actors, userIds, project } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);
    await setAway(tenant, userIds.admin, userIds.viewer);

    const issue = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "One hop only", assigneeId: userIds.member }),
    );

    expect(issue.assigneeId).toBe(userIds.admin);
  });

  it("leaves the assignment and its alert with an away member who has no delegate", async () => {
    const tenant = await createTenant("absence-no-delegate");
    const { org, actors, userIds, project } = tenant;
    await setAway(tenant, userIds.member, null);

    const issue = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Still theirs" }),
    );
    const assigned = await issueService.assignIssue(actors.owner, {
      orgId: org.id,
      issueId: issue.id,
      assigneeId: userIds.member,
    });

    expect(assigned.assigneeId).toBe(userIds.member);
    expect(await alertsFor(tenant, userIds.member, "issue_assigned")).toHaveLength(1);
  });

  it("applies from the start up to, but not including, the end", async () => {
    const tenant = await createTenant("absence-boundaries");
    const { org, actors, userIds, project } = tenant;
    const startsAt = Date.now() + 10 * HOUR;
    const endsAt = startsAt + HOUR;

    await setAbsence(actors.member, {
      orgId: org.id,
      userId: userIds.member,
      delegateUserId: userIds.admin,
      startsAt: toIsoTimestamp(new Date(startsAt)),
      endsAt: toIsoTimestamp(new Date(endsAt)),
      note: null,
    });

    const assigneeAt = async (instant: number) => {
      vi.useFakeTimers({ toFake: ["Date"] });
      vi.setSystemTime(instant);
      const issue = await issueService.createIssue(
        actors.owner,
        issueInput(org.id, project.id, { title: "Boundary", assigneeId: userIds.member }),
      );
      vi.useRealTimers();
      return issue.assigneeId;
    };

    expect(await assigneeAt(startsAt - 1)).toBe(userIds.member);
    expect(await assigneeAt(startsAt)).toBe(userIds.admin);
    expect(await assigneeAt(endsAt - 1)).toBe(userIds.admin);
    expect(await assigneeAt(endsAt)).toBe(userIds.member);
  });

  it("keeps issues that were already assigned, and moves nothing back afterwards", async () => {
    const tenant = await createTenant("absence-existing");
    const { org, actors, userIds, project } = tenant;

    const mine = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Already mine", assigneeId: userIds.member }),
    );
    await setAway(tenant, userIds.member, userIds.admin);
    const redirected = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Arrived while away", assigneeId: userIds.member }),
    );
    await clearAbsence(actors.member, org.id, userIds.member);

    expect((await issueRepo.findIssueById(org.id, mine.id))?.assigneeId).toBe(userIds.member);
    expect((await issueRepo.findIssueById(org.id, redirected.id))?.assigneeId).toBe(userIds.admin);
  });

  it("keeps workspaces independent for a user who belongs to both", async () => {
    const tenant = await createTenant("absence-two-orgs");
    const other = await createTenant("absence-two-orgs-other");
    const shared = await userRepo.insertUser({
      email: "shared@absence-two-orgs.test",
      name: "Shared",
      passwordHash: "seed",
    });
    await memberRepo.insertMember(tenant.org.id, shared.id, "member", null);
    await memberRepo.insertMember(other.org.id, shared.id, "member", null);
    await setAway(tenant, shared.id, tenant.userIds.admin);

    expect(await getAbsence(other.actors.owner, other.org.id, shared.id)).toBeNull();

    const issue = await issueService.createIssue(
      other.actors.owner,
      issueInput(other.org.id, other.project.id, { title: "Other workspace", assigneeId: shared.id }),
    );
    expect(issue.assigneeId).toBe(shared.id);
  });
});

describe("member removal", () => {
  it("removes the member's own absence and drops delegations pointing at them", async () => {
    const tenant = await createTenant("absence-removal");
    const { org, actors, userIds, project } = tenant;
    await setAway(tenant, userIds.member, userIds.viewer);
    await setAway(tenant, userIds.viewer, userIds.admin);

    await removeMember(actors.owner, {
      orgId: org.id,
      memberId: await memberIdOf(tenant, userIds.viewer),
    });

    expect(await memberRepo.findAbsence(org.id, userIds.viewer)).toBeNull();

    const remaining = await getAbsence(actors.owner, org.id, userIds.member);
    expect(remaining).not.toBeNull();
    expect(remaining?.delegateUserId).toBeNull();

    const issue = await issueService.createIssue(
      actors.owner,
      issueInput(org.id, project.id, { title: "Nobody left to cover", assigneeId: userIds.member }),
    );
    expect(issue.assigneeId).toBe(userIds.member);
  });
});

describe("overdue alerts while away", () => {
  const PAST = "2026-01-01T00:00:00.000Z";
  const SWEEP = new Date("2026-06-01T07:00:00.000Z");

  async function overdueIssueFor(tenant: Tenant, assigneeId: UserId) {
    await usageRepo.recomputeUsage(tenant.org.id);
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    return issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Late", assigneeId, dueAt: PAST }),
      tenant.userIds.owner,
      number,
    );
  }

  async function setAwayAround(
    tenant: Tenant,
    actor: Actor,
    delegateUserId: UserId | null,
    startsAt: Date,
    endsAt: Date,
  ) {
    await setAbsence(actor, {
      orgId: tenant.org.id,
      userId: actor.userId,
      delegateUserId,
      startsAt: toIsoTimestamp(startsAt),
      endsAt: toIsoTimestamp(endsAt),
      note: null,
    });
  }

  it("alerts the delegate instead of the away assignee, leaving the sweep alone", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue");
    const { userIds, actors } = tenant;
    const issue = await overdueIssueFor(tenant, userIds.member);
    await setAwayAround(tenant, actors.member, userIds.admin, SWEEP, new Date(SWEEP.getTime() + HOUR));

    const seen: (UserId | null)[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        if (payload.issueId === issue.id) seen.push(payload.assigneeId);
      }),
    );

    await runOverdueIssueJob(SWEEP);

    expect(seen).toEqual([userIds.member]);
    expect(await alertsFor(tenant, userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, userIds.member, "issue_overdue")).toHaveLength(0);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.assigneeId).toBe(userIds.member);
  });

  it("alerts the assignee when the absence has ended by the time of the sweep", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue-ended");
    const { userIds, actors } = tenant;
    await overdueIssueFor(tenant, userIds.member);
    await setAwayAround(tenant, actors.member, userIds.admin, new Date(SWEEP.getTime() - HOUR), SWEEP);

    await runOverdueIssueJob(SWEEP);

    expect(await alertsFor(tenant, userIds.member, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, userIds.admin, "issue_overdue")).toHaveLength(0);
  });

  it("alerts an away assignee who has no delegate", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue-no-delegate");
    const { userIds, actors } = tenant;
    await overdueIssueFor(tenant, userIds.member);
    await setAwayAround(tenant, actors.member, null, new Date(SWEEP.getTime() - HOUR), new Date(SWEEP.getTime() + HOUR));

    await runOverdueIssueJob(SWEEP);

    expect(await alertsFor(tenant, userIds.member, "issue_overdue")).toHaveLength(1);
  });
});

describe("mentions while away", () => {
  async function commentMentioning(tenant: Tenant, author: Actor, mentioned: readonly UserId[]) {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention thread" }),
    );
    return commentService.createComment(author, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Could you take a look?",
      parentId: null,
      mentionedUserIds: [...mentioned],
    });
  }

  it("alerts both the away member and their delegate", async () => {
    const tenant = await createTenant("absence-mention");
    const { userIds, actors } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);

    await commentMentioning(tenant, actors.owner, [userIds.member]);

    expect(await alertsFor(tenant, userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, userIds.admin, "comment_mention")).toHaveLength(1);
  });

  it("alerts a delegate who is also mentioned directly only once", async () => {
    const tenant = await createTenant("absence-mention-once");
    const { userIds, actors } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);

    await commentMentioning(tenant, actors.owner, [userIds.member, userIds.admin]);

    expect(await alertsFor(tenant, userIds.admin, "comment_mention")).toHaveLength(1);
  });

  it("never alerts the author, even as somebody's delegate", async () => {
    const tenant = await createTenant("absence-mention-author");
    const { userIds, actors } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);

    await commentMentioning(tenant, actors.admin, [userIds.member]);

    expect(await alertsFor(tenant, userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, userIds.member, "comment_mention")).toHaveLength(1);
  });

  it("applies the delegate's own notification preferences", async () => {
    const tenant = await createTenant("absence-mention-prefs");
    const { org, userIds, actors } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);
    await preferenceRepo.upsertPreference({
      orgId: org.id,
      userId: userIds.admin,
      kind: "comment_mention",
      inApp: false,
      email: false,
      digestOnly: false,
    });

    await commentMentioning(tenant, actors.owner, [userIds.member]);

    expect(await alertsFor(tenant, userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, userIds.member, "comment_mention")).toHaveLength(1);
  });

  it("alerts only the mentioned member once their absence is cleared", async () => {
    const tenant = await createTenant("absence-mention-cleared");
    const { org, userIds, actors } = tenant;
    await setAway(tenant, userIds.member, userIds.admin);
    await clearAbsence(actors.member, org.id, userIds.member);

    await commentMentioning(tenant, actors.owner, [userIds.member]);

    expect(await alertsFor(tenant, userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, userIds.admin, "comment_mention")).toHaveLength(0);
  });
});
